CREATE TABLE r (
    id VARCHAR(100) PRIMARY KEY
);

CREATE TABLE ca (
    id VARCHAR(100) PRIMARY KEY,
    rid VARCHAR(100) NOT NULL,
    a INTEGER NOT NULL
);

CREATE TABLE cb (
    id VARCHAR(100) PRIMARY KEY,
    rid VARCHAR(100) NOT NULL,
    b BIT NOT NULL
);

CREATE TABLE cc (
    id VARCHAR(100) PRIMARY KEY,
    rid VARCHAR(100) NOT NULL,
    c DATETIMEOFFSET(7) NOT NULL
);

